package com.zc.agent.core.modules.runtime.controller;import com.zc.agent.core.common.response.ApiResponse;import com.zc.agent.core.modules.runtime.service.PromptExperimentObservationService;import org.springframework.web.bind.annotation.*;import java.util.*;
/** Prompt 实验曝光与运行结果指标 API。 */@RestController @RequestMapping("/api/core/prompt-experiments")public class PromptExperimentObservationController{private final PromptExperimentObservationService s;public PromptExperimentObservationController(PromptExperimentObservationService s){this.s=s;}@GetMapping("/metrics")public ApiResponse<List<Map<String,Object>>>metrics(@RequestParam(required=false)Long experimentId){return ApiResponse.success(s.metrics(experimentId));}}
